<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'superadmin', false);

start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='superadmin'){header('Location: ../auth/login.php');exit;}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id&&in_array($status,['new','read','resolved'],true)){$st=$conn->prepare('UPDATE contact_messages SET status=? WHERE id=?');$st->bind_param('si',$status,$id);$st->execute();$st->close();$msg='Inquiry status updated.';}}
$rows=[];$r=$conn->query("SELECT * FROM contact_messages ORDER BY FIELD(status,'new','read','resolved'),created_at DESC");if($r){while($x=$r->fetch_assoc())$rows[]=$x;}
require '../includes/ui.php';ui_header('Public Inquiries','superadmin');ui_sidebar('superadmin','inquiries.php');?>
<div class="page-head"><div><div class="eyebrow">CONTACT US</div><h1>Public Inquiries</h1><div class="muted">Messages submitted from the SupremeDent landing page.</div></div><span class="badge"><?=count($rows)?> total</span></div><?php if($msg)flash('success',$msg);?><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Sender</th><th>Subject / Message</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No public inquiries yet.</td></tr><?php endif;?><?php foreach($rows as $x):?><tr><td><b><?=e($x['name'])?></b><br><span class="muted"><?=e($x['email'])?></span><br><span class="muted"><?=e($x['phone']?:'No phone')?></span></td><td><b><?=e($x['subject']?:'General inquiry')?></b><br><span><?=nl2br(e($x['message']))?></span></td><td><?=e(date('M d, Y h:i A',strtotime($x['created_at'])))?></td><td><span class="badge"><?=e(ucfirst($x['status']))?></span></td><td><form method="post" class="inquiry-action"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="status"><option value="new" <?=$x['status']==='new'?'selected':''?>>New</option><option value="read" <?=$x['status']==='read'?'selected':''?>>Read</option><option value="resolved" <?=$x['status']==='resolved'?'selected':''?>>Resolved</option></select><button class="btn btn-secondary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section><style>.inquiry-action{display:flex;gap:6px}.inquiry-action select{border:1px solid var(--border);border-radius:8px;padding:8px}</style><?php ui_footer(); ?>
